// ============================================================
// 增量 1000 条技术条目生成器
// 目标：在现有 1342 节点 DAG 之上，新增 1000 条全新、真实、可分的技术条目
// 原则：
//   1) 每条新技术的 dependsOn 只引用「已存在」的 id（含上一轮 extend/extra/data）
//      —— 保证依赖全部可解析，且整图天然无环（新节点只挂在既有 DAG 之上）
//   2) 简介由「技术名 + 真实上游名 + 具体用途」合成，非模板套话、≥40 字、点名上下游
//   3) 自带校验：重复 id / 依赖闭合 / DAG 无环 / 简介质量（禁语、长度）
// 产出：assets/techs_more.js  (const MORE_TECHS = [...])
// 运行：node tools/gen_1000.js
// ============================================================
const fs = require("fs");
const path = require("path");

// ---------- 载入既有库，取得已有 id 集合 ----------
const exSrc = fs.readFileSync(path.join(__dirname, "..", "assets", "techs_extra.js"), "utf8");
const extSrc = fs.readFileSync(path.join(__dirname, "..", "assets", "techs_extend.js"), "utf8");
const dataSrc = fs.readFileSync(path.join(__dirname, "..", "assets", "data.js"), "utf8").replace(/if \(typeof module[\s\S]*$/, "");
const D = (new Function(
  exSrc + "\n" + extSrc + "\n" + dataSrc + "\nreturn {TECHS, CATEGORIES, ERAS};"
))();
const EXIST = new Set(D.TECHS.map(t => t.id));
const CATNAMES = {}; D.CATEGORIES.forEach(c => CATNAMES[c.id] = c.name);
const ERANAME = {}; D.ERAS.forEach(e => ERANAME[e.id] = e.name);

// ---------- 条目构造 ----------
// 字段：id,name,en,category,era,date,year,dependsOn,summary[,tier]
// 依赖只引用 EXIST 中的真实 id
const RAW = [];

// 便捷推送（用于程序化批量）
