// ===================== 精准裁剪到 1000 条（按类别分层，保留全部未来条目） =====================
(function capTo1000() {
  const TARGET = 1000;
  const fut = RAW.filter(t => t.era === "future");
  const rest = RAW.filter(t => t.era !== "future");
  const rem = TARGET - fut.length;
  const byCat = {};
  rest.forEach(t => { (byCat[t.category] = byCat[t.category] || []).push(t); });
  const cats = Object.keys(byCat);
  const totalRest = rest.length;
  const allocated = {};
  let sum = 0;
  cats.forEach(c => { allocated[c] = Math.round(rem * byCat[c].length / totalRest); sum += allocated[c]; });
  let diff = rem - sum;
  cats.sort((a, b) => byCat[b].length - byCat[a].length);
  let ci = 0, guard = 0;
  while (diff !== 0 && guard++ < cats.length * 10) {
    const c = cats[ci % cats.length];
    if (diff > 0 && allocated[c] < byCat[c].length) { allocated[c]++; diff--; }
    else if (diff < 0 && allocated[c] > 0) { allocated[c]--; diff++; }
    ci++;
  }
  const kept = [];
  cats.forEach(c => { kept.push(...byCat[c].slice(0, allocated[c])); });
  RAW.length = 0;
  fut.forEach(t => RAW.push(t));
  kept.forEach(t => RAW.push(t));
})();

// ===================== 简介合成 =====================
function depNamesOf(t) {
  return (t.dependsOn || []).map(d => {
    const e = D.TECHS.find(x => x.id === d);
    return e ? e.name : d;
  });
}
function summarize(t) {
  const catName = CATNAMES[t.category] || "技术";
  const eraName = ERANAME[t.era] || "";
  const up = depNamesOf(t);
  const upStr = up.length ? up.join("、") : "基础原理";
  const p = t.purpose || "推进该领域的技术图景";
  const variants = [
    `以${upStr}为基，${t.name}专攻${p}，把${catName}的能力边界再往前推一步。`,
    `${t.name}把${upStr}的成果用于${p}，让${catName}从原理走向可部署的工程现实。`,
    `在${upStr}之上，${t.name}聚焦于${p}，是${catName}走向更精细、更可控的关键环节。`,
    `承接${upStr}，${t.name}解决${p}，填补了${catName}在${eraName}的一项具体空白。`
  ];
  let h = 0; for (const c of t.id) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  return variants[h % variants.length];
}
// 注入 summary
RAW.forEach(t => { if (!t.summary) t.summary = summarize(t); });

// ===================== 校验 =====================
const NEW_IDS = new Set(RAW.map(t => t.id));
const dups = [], missing = [], seen = new Set();
const BANNED = /奠定了.{0,12}基础框架|发展成熟|基础设施|重要进展|关键技术（泛称）|关键技术$/;
const badSummary = [];
RAW.forEach(t => {
  if (seen.has(t.id)) dups.push(t.id);
  seen.add(t.id);
  (t.dependsOn || []).forEach(d => { if (!EXIST.has(d) && !NEW_IDS.has(d)) missing.push(t.id + " -> " + d); });
  if (!t.summary || t.summary.length < 40 || BANNED.test(t.summary)) badSummary.push(t.id);
});
// DAG 无环：新节点只依赖 EXIST 或 NEW_IDS，且 NEW_IDS 内部不互相依赖（本生成器约定），故天然无环
// 但仍做一次全图 Kahn 校验
const allIds = new Set([...EXIST, ...NEW_IDS]);
const graph = new Map(); allIds.forEach(id => graph.set(id, []));
D.TECHS.forEach(t => (t.dependsOn || []).forEach(d => { if (graph.has(t.id) && graph.has(d)) graph.get(t.id).push(d); }));
RAW.forEach(t => (t.dependsOn || []).forEach(d => { if (graph.has(t.id) && graph.has(d)) graph.get(t.id).push(d); }));
const indeg = new Map(); allIds.forEach(id => indeg.set(id, 0));
graph.forEach((deps, id) => deps.forEach(d => indeg.set(d, indeg.get(d) + 1)));
const q = []; allIds.forEach(id => { if (indeg.get(id) === 0) q.push(id); });
let visited = 0;
while (q.length) { const id = q.shift(); visited++; graph.get(id).forEach(d => { indeg.set(d, indeg.get(d) - 1); if (indeg.get(d) === 0) q.push(d); }); }
const cycle = visited !== allIds.size;

let ok = true;
function fail(msg) { ok = false; console.error("✗ " + msg); }
if (dups.length) fail("重复 id: " + dups.join(", "));
if (missing.length) fail("依赖未解析 (" + missing.length + "): " + missing.slice(0, 40).join(" | "));
if (cycle) fail("检测到依赖环（仅拓扑访问 " + visited + "/" + allIds.size + " 节点）");
if (badSummary.length) fail("简介质量不合格 (" + badSummary.length + "): " + badSummary.slice(0, 20).join(", "));
if (RAW.length < 1000) fail("条目数 " + RAW.length + " 少于 1000");

const tierCount = {}; const eraCount = {}; const catCount = {};
RAW.forEach(t => { if (t.tier) tierCount[t.tier] = (tierCount[t.tier]||0)+1; eraCount[t.era] = (eraCount[t.era]||0)+1; catCount[t.category] = (catCount[t.category]||0)+1; });
if (!ok) { console.error("\n校验未通过，未写出文件。"); process.exit(1); }
console.log("✓ 校验通过");
console.log("  新增条目: " + RAW.length);
console.log("  按时期: " + JSON.stringify(eraCount));
console.log("  按分级: " + JSON.stringify(tierCount));
console.log("  按类别: " + JSON.stringify(catCount));

